contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 bit) public payable {
        require(bit < 32, "bit out of range");

        bytes4 erc165Id = 0x01ffc9a7;
        bytes4 mutatedId = bytes4(uint32(erc165Id) ^ (uint32(1) << bit));
        bool expected = (mutatedId == erc165Id);

        bool ret = c.supportsInterface(mutatedId);

        assert(ret == expected);
    }

    receive() external payable {}
}

